<script setup lang="ts">
import { serviceCatalog } from '../services';
import ActivityServerLink from './ActivityServerLink.vue';
import UiInput from './UiInput.vue';
import UiSelect from './UiSelect.vue';
import RefreshButton from './RefreshButton.vue';
import RelativeDate from './RelativeDate.vue';
import { onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { call } from '../api';
import type { ActivityPage,MonitoringTarget } from '../types';
const emit=defineEmits<{monitoring:[target:MonitoringTarget]}>();
const view=ref<ActivityPage>(),category=ref(''),phase=ref(''),search=ref(''),error=ref(''),busy=ref(false);
const cursors=ref<(string|null)[]>([null]),index=ref(0);
const categories:Record<string,string>={ssh:'SSH',server:'Server',ai:'AI',mcp:'MCP',process:'Process',app:'App'};
const phases:Record<string,string>={started:'Started',completed:'Finished',failed:'Failed',cancelled:'Cancelled',interrupted:'Interrupted',info:'Event'};
const serviceLabels = Object.assign({}, ...Object.values(serviceCatalog).map(spec => spec.activityLabels));
const actions:Record<string,string>={...serviceLabels,console_command:"SSH command",start_console_chat:"Console conversation message",add_service_instance:"Add service connection",remove_service_instance:"Removal of service connection",rename_service_instance:"Change of service signature (history)",script_cancelled_by_user:"Request cancelled by the user",script_grant_revoked:"Launch clearance withdrawn",script_rollback_started:"Configuration rollback",script_rollback_result:"Outcome of rollback",script_proposed:"Requesting AI action",script_review_started:"Low-risk testing",script_review_completed:"Results of the low inspection",script_awaiting_approval:"Waiting for permission",script_execution_started:"Execution of permitted action",script_result:"Outcome of action",script_approved_once:"The action is allowed once",script_approved_session:"Launch clearance issued",script_denied:"Action denied",script_request:"The Managed Action of AI",exec:"Request for shell",cat:"Reading the file",grep:"File search",ls:"Reading the catalog",du:"Estimation of catalog size",awk:"Reading file fields",sed:"Reading lines of file",action_approval_notification:"Notification of request for authorization",set_vulnerability_hidden:'Changing the visibility of vulnerability',resolve_incident:'Incident resolved manually',configure_monitoring:'Setting up monitoring',configure_notifications:'Set-up of notifications',notification_permission:'Request for authorization of notices',notification_test:'Notification test',notification_send:'Sending notice',notification_overflow:'Overflow of the notification queue',notification_unavailable:'Notifications not available',notification_queue_error:'Error in the notification queue','logs.collect':'Log analysis','packages.collect':'Updating packages','packages.collect_apt':'APT vetting','services.collect_for':'Diagnostics of service','auth.claude_token':'Claude Authorization Verification',detect_agents:'CLI check',poll:'Server polling',startup:'Launch of the application',shutdown:'Completion of the annex',window_hidden:'Window hidden',storage_cleanup:'Cleaning the vault',pick_inventory_file:'Choice of inventory',add_source:'Addition of servers',sync_source:'Update of inventory',monitoring_wake:'Resuming monitoring after sleep',refresh_source:'Updating the server list',delete_source:'Deletion of the server list',save_settings:'Saving settings',update_settings:'Change of settings',poll_server:'Updating metrics',diagnose:'Updating the logs',refresh_packages:'Updating packages',refresh_apt:'APT vetting',refresh_advisories:'Updating of the advisories',update_source:'Downloading of advisories',update_cvss:'Update of CVE assessments',configure_service:'Setting up the diagnostic service',refresh_service:'Diagnostics of service',start_investigation:'Message in the server dialog',cancel_investigation:'Stopping AI startups',save_server_dependencies:'Changing dependencies of servers',start_group_investigation:'Start of group investigation',resume_auto:'Reviving AI',dismiss_auto_job:'Skipping an automatic task',new_check:'Creation of verification',save_check_version:'Saving the Verification Version',test_check_version:'Testing of verification',preview_check_version:'Test run of verification',activate_check:'Incorporation of verification',disable_check:'Turning off the check',discard_check_version:'Deletion of the verification version',delete_check:'Deletion of verification',run_checks:'Initiation of inspections',create_check_with_agent:'Creating verification with AI',open_server:'Opening the server window',launch:'Isolated analyzer',preflight:'Testing AI isolation',rejected_tool:'Prohibited MCP Tool'};
let generation=0,disposed=false,timer:ReturnType<typeof setInterval>|undefined,debounce:ReturnType<typeof setTimeout>|undefined;
async function load(){
 const current=++generation;busy.value=true;error.value='';
 try {const result=await call<ActivityPage>('activity_log',{query:{before:cursors.value[index.value],category:category.value||null,phase:phase.value||null,search:search.value.trim()||null}});if(!disposed&&current===generation)view.value=result;}
 catch(e){if(!disposed&&current===generation)error.value=String(e).replace(/^Error: /,'');}
 finally{if(!disposed&&current===generation)busy.value=false;}
}
function refresh(){cursors.value=[null];index.value=0;void load();}
function older(){if(!view.value?.next||busy.value)return;cursors.value=cursors.value.slice(0,index.value+1);cursors.value.push(view.value.next);index.value++;void load();}
function newer(){if(index.value===0||busy.value)return;index.value--;void load();}
watch([category,phase,search],()=>{generation++;busy.value=true;clearTimeout(debounce);debounce=setTimeout(refresh,250);});
function visible(){if(!document.hidden&&index.value===0&&!busy.value)void load();}
onMounted(()=>{void load();timer=setInterval(visible,10000);document.addEventListener('visibilitychange',visible);});
onBeforeUnmount(()=>{disposed=true;generation++;clearInterval(timer);clearTimeout(debounce);document.removeEventListener('visibilitychange',visible);});
</script>
<template>
<section class="journal" :aria-busy="busy">
 <div class="toolbar"><UiSelect v-model="category" aria-label="Type of action"><option value="">All actions</option><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></UiSelect><UiSelect v-model="phase" aria-label="Outcome of action"><option value="">All results</option><option v-for="(label,key) in phases" :key="key" :value="key">{{label}}</option></UiSelect><UiInput v-model="search" type="search" maxlength="100" aria-label="Searching in the action log" placeholder="Server or ID address"/><RefreshButton :disabled="busy" @click="refresh">{{busy?'Update…':'Refresh'}}</RefreshButton></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <p v-if="view?.storage.error" class="error" role="alert">{{view.storage.error}}. Check the free space and rights, then restart the application.</p>
 <p v-if="view?.storage.dropped" class="notice" role="status">No recorded events: {{view.storage.dropped}}.</p>
 <p v-if="view?.expired" class="notice" role="status">These events have been rotated out. Refresh to see the latest events.</p>
 <p v-if="view?.skipped" class="notice" role="status">Damaged recordings missed: {{view.skipped}}.</p>
 <div v-if="view?.events.length" class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Server/Context</th><th>The result</th><th class="duration">Working hours</th></tr></thead><tbody><tr v-for="event in view.events" :key="event.id"><td class="at"><RelativeDate :at="event.at" unit="milliseconds"/></td><td :title="`ID: ${event.operationId}${event.runId?` · AI: ${event.runId}`:''}`"><span class="category">{{categories[event.category]??event.category}}</span><span class="action">{{actions[event.action]??event.action}}</span><small v-if="event.aiAction?.goal" class="action-meta">{{event.aiAction.goal}}</small><button v-if="event.monitoring" class="definition" :title="`Version ${event.monitoring.version}`" @click="emit('monitoring',{definitionId:event.monitoring.definitionId,serverId:event.monitoring.serverId,instanceId:event.monitoring.instanceId})">{{event.monitoring.definitionId}} · {{({schedule:'scheduled',manual:'manually',ai:'request',startup:'launch'} as Record<string,string>)[event.monitoring.trigger]??event.monitoring.trigger}}</button><small v-if="event.aiAction" class="action-meta" :title="`Request ${event.aiAction.requestId} · hash ${event.aiAction.artifactHash} · ${event.aiAction.rules} · ${event.aiAction.model}/${event.aiAction.effort}`">{{event.aiAction.model}}<template v-if="event.aiAction.tokens!=null"> · {{event.aiAction.tokens.toLocaleString('en-US')}} low-token</template></small></td><td class="target"><ActivityServerLink :event="event" empty="—"/></td><td><span class="phase" :class="event.phase">{{phases[event.phase]??event.phase}}</span></td><td class="duration">{{event.durationMs==null?'—':event.durationMs<1000?`${event.durationMs} ms`:`${(event.durationMs/1000).toFixed(1)} s`}}</td></tr></tbody></table></div>
 <p v-else-if="!busy&&!error&&!view?.expired" class="empty">{{view?.next?'There are no suitable events in this section. We can move on to older ones.':category||phase||search?'There are no suitable events.':'No action yet.'}}</p>
 <footer v-if="view"><span>{{(view.storage.bytes/1048576).toFixed(1)}} / {{Math.round(view.storage.limitBytes/1048576)}} MiB · old records are automatically deleted</span><div class="pagination"><button type="button" :disabled="busy||index===0" @click="newer">Novea</button><span>{{index+1}}</span><button type="button" :disabled="busy||!view.next" @click="older">Older</button></div></footer>
</section>
</template>
<style scoped>
.action-meta{display:block;font-size:10px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere}
.definition{font-size:10px;color:var(--accent);background:transparent;border:0;padding:3px 0;text-decoration:underline;text-underline-offset:3px}.journal{padding-bottom:24px}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:18px}button{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:7px 9px;min-width:0}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:hover:not(:disabled){background:var(--hover)}.toolbar>button{margin-left:auto}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}th{font-size:11px;font-weight:500;color:var(--muted);padding:8px 10px;border-bottom:1px solid var(--line)}td{padding:10px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.5}.at{font-size:11px;color:var(--muted);white-space:nowrap;font-variant-numeric:tabular-nums}.category{display:block;font-size:10px;color:var(--muted);margin-bottom:2px}.action{display:block;overflow-wrap:anywhere}.target{max-width:35ch;overflow-wrap:anywhere;color:var(--muted)}.duration{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--muted);font-size:11px}.phase{font-size:11px;white-space:nowrap;color:var(--muted)}.phase.completed{color:var(--success)}.phase.failed{color:var(--danger)}.phase.cancelled,.phase.interrupted{color:var(--warning)}footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:18px;color:var(--muted);font-size:11px}.pagination{display:flex;align-items:center;gap:12px}.pagination button{font-size:12px}.empty{padding:36px 0;color:var(--muted);font-size:13px}.error,.notice{padding:12px;border-radius:7px;font-size:12px;line-height:1.6;overflow-wrap:anywhere}.error{color:var(--danger);background:var(--danger-bg)}.notice{color:var(--warning);background:var(--warning-bg)}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:700px){.toolbar .ui-input{flex:1;min-width:150px}.toolbar>button{margin-left:0}td,th{padding:8px 6px}.duration{display:none}.target{max-width:23ch}.at{white-space:normal}}
</style>
